sys_script.script:
(function executeRule(current, previous) {
    try {
        gs.info('=== Calculate Duration with Holidays ===');

        // Only run when dates, country, or half_day fields change
        if (previous &&
            current.start_date.toString() === previous.start_date.toString() &&
            current.end_date.toString() === previous.end_date.toString() &&
            current.country.toString() === previous.country.toString() &&
            current.is_half_day == previous.is_half_day &&
            current.half_day_period == previous.half_day_period) {
            gs.info('No relevant changes, skipping calculation');
            return;
        }

        // Get country from employee profile if not set directly
        var countryValue = '';
        if (current.country && !current.country.nil()) {
            countryValue = current.country.toString();
            gs.info('Using country from form: ' + countryValue);
        } else if (current.employee && !current.employee.nil()) {
            var employeeGR = new GlideRecordSecure('sys_user');
            if (employeeGR.get(current.employee)) {
                if (employeeGR.country && !employeeGR.country.nil()) {
                    countryValue = employeeGR.country.toString();
                    gs.info('Using country from employee profile: ' + countryValue);

                    // Set the country field on the form
                    current.country = employeeGR.country;
                }
            }
        }

        if (!countryValue) {
            gs.addWarningMessage("Country not found in employee profile. Please contact HR to update your profile.");
            gs.info('Missing country information');
            return;
        }

        if (!current.start_date || !current.end_date) {
            gs.info('Missing required date fields');
            return;
        }

        // Debug the half-day field values
        gs.info('Is half day: ' + current.is_half_day);
        gs.info('Half day period: ' + current.half_day_period);

        // If half-day is selected, ensure end date equals start date
        if (current.is_half_day == true && current.start_date.toString() !== current.end_date.toString()) {
            current.end_date = current.start_date;
            gs.info('Set end date equal to start date for half-day request');
        }

        // Calculate working days excluding holidays and weekends
        var holidayMgr = new x_1800027_leve_sys.HolidayManager();

        // Extract only the date part (YYYY-MM-DD)
        var startDateStr = new GlideDateTime(current.start_date).getDate();
        var endDateStr = new GlideDateTime(current.end_date).getDate();

        var workingDays = holidayMgr.calculateWorkingDays(
            startDateStr,
            endDateStr,
            countryValue  // Use the countryValue variable instead of current.country.toString()
        );

        gs.info('Calculated working days: ' + workingDays);

        // Adjust for half day if needed - only if is_half_day is true
        if (current.is_half_day == true) {
            workingDays = workingDays - 0.5;
            gs.info('Adjusted for half day: ' + workingDays);
        }

        // Update duration field
        current.duration = workingDays;

        gs.info('Set duration to: ' + workingDays);

    } catch (ex) {
        gs.error('Error calculating duration: ' + ex);
        gs.error('Stack: ' + ex.stack);
    }
})(current, previous);
